import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("a single sword → base premium 100 G");
    it.todo("a single amulet → base premium 60 G");
    it.todo("a single staff → base premium 80 G");
    it.todo("a single potion → base premium 40 G");
    it.todo("a single rune → base premium 25 G");
    it.todo("a single moonstone → base premium 25 G");
    it.todo("a sword and an amulet → policy base premium 160 G");
  });

  describe("quote — building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-scoped modifiers", () => {
    it.todo("a cursed sword adds a 50 % surcharge on its base premium");
    it.todo("a sword with exactly enchantment 5 adds a 30 % high-enchantment surcharge");
    it.todo("a sword with enchantment 4 gets no high-enchantment surcharge");
    it.todo("a cursed sword with exactly enchantment 5 gets both surcharges");
    it.todo("a cursed sword and a plain amulet → 210 G before policy modifiers and fee (curse applies only to the cursed item)");
  });

  describe("quote — policy-scoped modifiers", () => {
    it.todo("a customer with exactly 2 years with MHPCO gets the 20 % loyalty discount");
    it.todo("a customer with 1 year with MHPCO gets no loyalty discount");
    it.todo("the first quote carries the 10 % initial assessment surcharge");
    it.todo("each quote after the first gets an additional 15 % follow-up contract discount");
    it.todo("the 5 G processing fee is added at the very end");
  });

  describe("quote — rounding", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, first contract) with a cursed sword (steel, enchantment 3) → premium 165 G");
    it.todo("long-standing customer (3 years), second quote, cursed sword (steel, enchantment 7) → premium 160 G");
  });

  describe("quote — errors", () => {
    it.todo("an item with an unknown type (e.g. broomstick) → error");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
  });

  describe("claim — special clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % clause, then deductible)");
    it.todo("sword with exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("claim — deductible per damage event", () => {
    it.todo("a dragon attack damaging an insured sword (500 G) and an insured amulet (300 G) → payout 600 G");
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects the premium only)");
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  });

  describe("claim — cap exhaustion across successive claims", () => {
    it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("two damages of type sword against a policy covering two swords → each gets its own deductible");
    it.todo("more damage entries of a type than the policy covers → error");
  });

  describe("claim — rounding", () => {
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — errors", () => {
    it.todo("a damage entry whose item is not part of the policy → error");
    it.todo("a damage entry with an unknown item type → error");
    it.todo("a damage entry with amount -200 → error");
  });

  describe("scenario processing", () => {
    it.todo("results are returned in the same order and length as the input steps");
    it.todo("a claim step refers to the policy created by an earlier quote step via its zero-based index");
  });
});

