export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const INITIAL_ASSESSMENT_SURCHARGE = 0.1;

const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
} as const satisfies Record<string, number>;

type InsurableItemType = keyof typeof BASE_PREMIUMS;

const isInsurableItemType = (type: string): type is InsurableItemType =>
  type in BASE_PREMIUMS;

// Unknown item types are not yet rejected — the spec requires an error, but no
// test drives that behaviour yet, so they are priced at 0 for the moment.
const UNPRICED_UNKNOWN_TYPE = 0;

const basePremiumForItem = (item: Item): number =>
  isInsurableItemType(item.type)
    ? BASE_PREMIUMS[item.type]
    : UNPRICED_UNKNOWN_TYPE;

const basePremiumForItems = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumForItem(item), 0);

const withInitialAssessmentSurcharge = (basePremium: number): number =>
  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);

const quotePremium = (items: Item[]): number =>
  Math.round(
    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
  );

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return { premium: quotePremium(step.items) };
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

