export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const INITIAL_ASSESSMENT_SURCHARGE = 0.1;

const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
} as const satisfies Record<string, number>;

type PricedItemType = keyof typeof BASE_PREMIUMS;

const hasBasePremium = (type: string): type is PricedItemType =>
  type in BASE_PREMIUMS;

// Unknown item types are not yet rejected — the spec requires an error, but no
// test drives that behaviour yet, so they are priced at 0 for the moment.
const UNPRICED_UNKNOWN_TYPE = 0;

const basePremiumForItem = (item: Item): number =>
  hasBasePremium(item.type)
    ? BASE_PREMIUMS[item.type]
    : UNPRICED_UNKNOWN_TYPE;

const BLOCK_SIZE = 3;

const BLOCK_BASE_PREMIUM = 60;

// A block is not carved out of a larger group: the block price applies only
// when the group consists of exactly three alike components (7 runes cost
// 7 × 25, not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only
// ever passes a single group from groupByType.
const isExactlyOneBlock = (group: Item[]): boolean =>
  group.length === BLOCK_SIZE;

const sum = (amounts: number[]): number =>
  amounts.reduce((total, amount) => total + amount, 0);

// "Alike" means the same exact type, not merely the same family: two runes and
// a moonstone are three components but not three alike ones, so grouping them
// by type keeps them apart and denies them the block price.
const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<string, Item[]>();
  for (const item of items) {
    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
  }
  return [...groups.values()];
};

const basePremiumForGroup = (group: Item[]): number =>
  isExactlyOneBlock(group)
    ? BLOCK_BASE_PREMIUM
    : sum(group.map(basePremiumForItem));

const basePremiumForItems = (items: Item[]): number =>
  sum(groupByType(items).map(basePremiumForGroup));

const CURSE_SURCHARGE = 0.5;

// Every modifier is an additive percentage of its OWN base — modifiers never
// compound with each other. Item-scoped modifiers take the affected item's base
// premium as their base; policy-scoped modifiers take the policy base premium
// (the sum of all item base premiums). So the total is always
// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
const modifierAmount = (rate: number, base: number): number => rate * base;

const HIGH_ENCHANTMENT_SURCHARGE = 0.3;

const HIGH_ENCHANTMENT_THRESHOLD = 5;

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

interface ItemModifier {
  rate: number;
  appliesTo: (item: Item) => boolean;
}

// Each item-scoped modifier is a row: a rate and the condition under which it
// applies. The predicate names the modifier, so a row needs no separate label.
// Adding a modifier means adding a row, not a new branch.
const ITEM_MODIFIERS: ItemModifier[] = [
  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
  { rate: HIGH_ENCHANTMENT_SURCHARGE, appliesTo: isHighlyEnchanted },
];

const itemModifierRates = (item: Item): number[] =>
  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
    (modifier) => modifier.rate,
  );

// Policy-scoped modifiers are a flat list of rates rather than predicate rows:
// unlike item modifiers, they do not select per item. The list is kept even
// though it holds one rate today, because the loyalty and follow-up contract
// discounts join it unchanged.
const POLICY_MODIFIER_RATES: number[] = [INITIAL_ASSESSMENT_SURCHARGE];

const itemModifiersTotal = (items: Item[]): number =>
  sum(
    items.flatMap((item) =>
      itemModifierRates(item).map((rate) =>
        modifierAmount(rate, basePremiumForItem(item)),
      ),
    ),
  );

const policyModifiersTotal = (policyBasePremium: number): number =>
  sum(
    POLICY_MODIFIER_RATES.map((rate) => modifierAmount(rate, policyBasePremium)),
  );

const quotePremium = (items: Item[]): number => {
  const policyBasePremium = basePremiumForItems(items);
  return Math.round(
    policyBasePremium +
      itemModifiersTotal(items) +
      policyModifiersTotal(policyBasePremium) +
      PROCESSING_FEE,
  );
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return { premium: quotePremium(step.items) };
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

