// Steps are not independent: a quote's premium depends on how many quotes came
// before it, and the pending claim operation will depend on the policies those
// quotes created. So a step is a function from state to (result, next state),
// and the scenario is a fold over that — not a map, which would promise an
// independence the steps do not have.
interface ScenarioState {
  quotesSoFar: number;
}

const INITIAL_STATE: ScenarioState = { quotesSoFar: 0 };

interface StepOutcome {
  result: StepResult;
  state: ScenarioState;
}

const runQuote = (
  step: QuoteStep,
  customer: Customer,
  state: ScenarioState,
): StepOutcome => ({
  result: {
    premium: quotePremium(step.items, customer, state.quotesSoFar > 0),
  },
  state: { ...state, quotesSoFar: state.quotesSoFar + 1 },
});

// Dispatch decides once what a step is; each operation then owns both its
// result and how it advances the state, so no caller has to re-test step.op to
// know what the step did.
const runStep = (
  step: Step,
  customer: Customer,
  state: ScenarioState,
): StepOutcome => {
  if (step.op === "quote") return runQuote(step, customer, state);
  throw new Error(`Unsupported step: ${step.op}`);
};

// The fold carries both halves of the outcome: the results accumulated so far
// and the state the next step will see. Threading the state explicitly (rather
// than recovering it from the last result) keeps the dependency between steps
// visible in the type.
interface ScenarioRun {
  results: StepResult[];
  state: ScenarioState;
}

const INITIAL_RUN: ScenarioRun = { results: [], state: INITIAL_STATE };

const appendStep =
  (customer: Customer) =>
  (run: ScenarioRun, step: Step): ScenarioRun => {
    const outcome = runStep(step, customer, run.state);
    return {
      results: [...run.results, outcome.result],
      state: outcome.state,
    };
  };

export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
  results: steps.reduce(appendStep(customer), INITIAL_RUN).results,
});

