  if (step.op === "quote") return runQuote(step, customer, state);
  throw new Error(`Unsupported step: ${step.op}`);
};

// The fold carries both halves of the outcome: the results accumulated so far
// and the state the next step will see. Threading the state explicitly (rather
// than recovering it from the last result) keeps the dependency between steps
// visible in the type.
interface ScenarioRun {
  results: StepResult[];
  state: ScenarioState;
}

const INITIAL_RUN: ScenarioRun = { results: [], state: INITIAL_STATE };

const appendStep =
  (customer: Customer) =>
  (run: ScenarioRun, step: Step): ScenarioRun => {
    const outcome = runStep(step, customer, run.state);
    return {
      results: [...run.results, outcome.result],
      state: outcome.state,
    };
  };

export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
  results: steps.reduce(appendStep(customer), INITIAL_RUN).results,
