interface StepOutcome {
  result: StepResult;
  state: ScenarioState;
}

// Both operations end by filing a policy under its quote's index — a claim
// re-files the same policy with a drawn-down cap. Naming that once keeps the
// Map out of the operations, so neither has to know how policies are stored.
const withPolicy = (
  state: ScenarioState,
  policyIndex: number,
  policy: Policy,
): ScenarioState => ({
  ...state,
  policies: new Map(state.policies).set(policyIndex, policy),
});

const runQuote = (
  step: QuoteStep,
  customer: Customer,
  state: ScenarioState,
  stepIndex: number,
): StepOutcome => ({
  result: {
    premium: quotePremium(step.items, customer, state.quotesSoFar > 0),
  },
  state: withPolicy(
    { ...state, quotesSoFar: state.quotesSoFar + 1 },
    stepIndex,
