const countByType = (types: string[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const type of types) {
    counts.set(type, (counts.get(type) ?? 0) + 1);
  }
  return counts;
};

// A damage entry claims one insured item, so a type cannot be damaged more
// times than the policy covers it. Checked before any payout is computed: the
// spec rejects the whole claim, not just the surplus entries.
const rejectOverClaiming = (policy: Policy, incident: Incident): void => {
  const insured = countByType(policy.items.map((item) => item.type));
  const claimed = countByType(
    incident.damages.map((damage) => damage.itemType),
  );
  for (const [type, claimedCount] of claimed) {
    const insuredCount = insured.get(type) ?? 0;
    if (claimedCount > insuredCount) {
      throw new Error(
        `Policy covers ${insuredCount} ${type}(s) but the claim names ${claimedCount}`,
      );
    }
  }
};

const payoutForIncident = (policy: Policy, incident: Incident): number => {
  rejectOverClaiming(policy, incident);
  return sum(
    incident.damages.map((damage) =>
      payoutForDamage(damage, anInsuredItemOfDamagedType(policy, damage)),
    ),
  );
};

